import org.jf.dexlib2.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;import java.io.*;import java.util.*;
/** Semantic instruction comparison, independent of DEX pool/index reordering. */
public class VerifyPackedArrayDelta {
 static Map<String,ClassDef> load(String path)throws Exception{Map<String,ClassDef> m=new TreeMap<>();var apk=DexFileFactory.loadDexContainer(new File(path),Opcodes.forApi(28));for(String n:apk.getDexEntryNames())for(ClassDef c:apk.getEntry(n).getDexFile().getClasses())if(m.put(c.getType(),c)!=null)throw new AssertionError("duplicate");return m;}
 static String value(Instruction i)throws Exception{StringBuilder s=new StringBuilder(i.getOpcode().toString());Set<String> methods=new TreeSet<>();for(Class<?> it:i.getClass().getInterfaces())for(var m:it.getMethods())if(m.getParameterCount()==0&&!m.getName().equals("getCodeUnits"))methods.add(m.getName());for(String n:methods){Object v=i.getClass().getMethod(n).invoke(i);if(n.equals("getSwitchElements")){StringBuilder q=new StringBuilder();for(Object o:(java.util.List)v){SwitchElement e=(SwitchElement)o;q.append(e.getKey()).append(':').append(e.getOffset()).append(',');}v=q.toString();}s.append('|').append(n).append('=').append(v);}return s.toString();}
 public static void main(String[]a)throws Exception{var left=load(a[0]);var right=load(a[1]);if(!left.keySet().equals(right.keySet()))throw new AssertionError("class inventory");int count=0,methods=0;Set<String> changed=new TreeSet<>();for(String n:left.keySet()){var l=left.get(n).getMethods().iterator();var r=right.get(n).getMethods().iterator();while(l.hasNext()){Method lm=l.next(),rm=r.next();methods++;if(!lm.toString().equals(rm.toString()))throw new AssertionError("method signature");if(lm.getImplementation()==null){if(rm.getImplementation()!=null)throw new AssertionError();continue;}var li=lm.getImplementation().getInstructions().iterator();var ri=rm.getImplementation().getInstructions().iterator();while(li.hasNext()){Instruction x=li.next(),y=ri.next();if(!value(x).equals(value(y))){if(x.getOpcode()!=y.getOpcode()||!(x instanceof ReferenceInstruction)||!(((ReferenceInstruction)x).getReference() instanceof StringReference)||!lm.getName().equals("<clinit>"))throw new AssertionError("non-string delta "+n+" "+lm+"\nLEFT "+value(x)+"\nRIGHT "+value(y));count++;changed.add(n);}}if(ri.hasNext())throw new AssertionError("instruction count");}if(r.hasNext())throw new AssertionError("method count");}if(count!=2||!changed.equals(Set.of("Lle;","Lcom/google/cardboard/sdk/R$styleable;")))throw new AssertionError(changed+" "+count);System.out.println("PASS classes="+left.size()+" methods="+methods+" only changed instructions="+count+" classes="+changed);}
}
